#include <iostream>
using std::cin;
using std::cout;
using std::max;

int main (void) {
	// 入力
	int h, w, n;
	cin >> h >> w >> n;
	int a[h][w];
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			cin >> a[i][j];
		}
	}
	int b[n];
	for (int i = 0; i < n; i++) {
		cin >> b[i];
	}

	// 答えを求め、変数 ans に記録
	int ans = 0;
	int rowcount[h]; 
	for (int i = 0; i < h; i++) {
		// 行 i における答えを求める (rowcount[i])
		rowcount[i] = 0;
		for (int j = 0; j < w; j++) {
			bool isfound = false; // a[i][j] が b に入っているとき true
			for (int k = 0; k < n; k++) {
				if (b[k] == a[i][j]) isfound = true;
			}
			if (isfound) {
				rowcount[i] += 1;
			}
		}
		// ans を更新する
		ans = max(ans, rowcount[i]);
	}

	// 出力
	cout << ans << "\n";

	return 0;
}
